import { useState, type FormEvent } from 'react';
import {
  JxButton,
  JxInputField,
  JxToastViewport,
  useJxToastQueue,
} from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');
  const [error, setError] = useState('');

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    const value = email.trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
      setError('Введите адрес в формате name@example.com');
      return;
    }

    setError('');
    setEmail('');
    toasts.push({
      title: 'Готово',
      message: `Письмо отправлено на ${value}`,
      variant: 'success',
    });
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-gap, 12px)',
        maxWidth: '420px',
        padding: 'var(--jx-gap-lg, 20px)',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
      }}
    >
      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        placeholder="name@example.com"
        value={email}
        onChange={(event) => {
          setEmail(event.target.value);
          if (error) setError('');
        }}
        errorText={error}
        helperText={error ? undefined : 'Раз в неделю, без спама'}
      />

      <JxButton type="submit" variant="primary">
        Подписаться
      </JxButton>

      <JxToastViewport
        items={toasts.items}
        onDismiss={toasts.dismiss}
        position="bottom-right"
      />
    </form>
  );
}

